// Emergency Response Tool
const emergencyData = {
  message: $input.all()[0].json.message || '',
  user_email: $input.all()[0].json.user_email || '',
  session_id: $input.all()[0].json.session_id || '',
  timestamp: new Date().toISOString(),
  priority: 'URGENT',
  type: 'emergency_contact',
  escalated: true
};

// Determine emergency type
const message = emergencyData.message.toLowerCase();
let emergencyType = 'general_emergency';

if (message.includes('leak')) {
  emergencyType = 'roof_leak';
} else if (message.includes('storm') || message.includes('wind') || message.includes('hail')) {
  emergencyType = 'storm_damage';
} else if (message.includes('collapse') || message.includes('structural') || message.includes('falling')) {
  emergencyType = 'structural_concern';
} else if (message.includes('safety') || message.includes('dangerous')) {
  emergencyType = 'safety_hazard';
}

const response = {
  emergency_logged: true,
  emergency_type: emergencyType,
  priority_level: 'URGENT',
  immediate_action: 'Call (970) 446-8995 for immediate emergency assistance',
  response_message: `🚨 EMERGENCY DETECTED 🚨\n\nI understand this is an urgent situation. For immediate emergency assistance, please call us right now at (970) 446-8995.\n\nOur emergency response team is available 24/7 for situations like ${emergencyType.replace('_', ' ')}.\n\nWhile you're calling, here are immediate steps:\n- If there's water coming in, place buckets to catch drips\n- If it's safe, take photos for insurance\n- Keep the area clear of people and valuables\n\nWe'll dispatch a technician as soon as possible. Your safety is our top priority.`
};

return { json: { ...emergencyData, ...response } };

// Calendar Scheduling Tool
const schedulingData = {
  calendly_link: 'https://calendly.com/jimmy-agenticpersonnel/30min',
  available_services: [
    'Free Roof Inspection',
    'Damage Assessment',
    'Estimate Consultation',
    'Maintenance Check',
    'Insurance Claim Support'
  ],
  typical_availability: 'Monday-Friday 8AM-6PM, Saturday 9AM-4PM',
  emergency_scheduling: 'Call (970) 446-8995 for emergency appointments'
};

const message = $input.all()[0].json.message?.toLowerCase() || '';
let serviceType = 'general_consultation';
let urgency = 'standard';

if (message.includes('inspection')) {
  serviceType = 'roof_inspection';
} else if (message.includes('estimate') || message.includes('quote')) {
  serviceType = 'estimate_consultation';
} else if (message.includes('emergency') || message.includes('urgent')) {
  serviceType = 'emergency_assessment';
  urgency = 'urgent';
} else if (message.includes('insurance') || message.includes('claim')) {
  serviceType = 'insurance_consultation';
}

let responseMessage = '';

if (urgency === 'urgent') {
  responseMessage = `For urgent scheduling needs, please call us immediately at (970) 446-8995.\n\nOur team can often accommodate same-day or next-day emergency appointments.`;
} else {
  responseMessage = `I'd be happy to help you schedule a ${serviceType.replace('_', ' ')}!\n\n📅 **Schedule Online:** ${schedulingData.calendly_link}\n\n⏰ **Typical Availability:** ${schedulingData.typical_availability}\n\n🏠 **Available Services:**\n${schedulingData.available_services.map(service => `• ${service}`).join('\n')}\n\nFor immediate scheduling or if you have questions, call us at (970) 446-8995.`;
}

return {
  json: {
    scheduling_provided: true,
    service_type: serviceType,
    urgency: urgency,
    calendly_link: schedulingData.calendly_link,
    response_message: responseMessage
  }
};

