// Format final response for webhook
const agentResponse = $('Alpine Peak AI Agent').item.json;
const inputData = $('Message Merger').item.json;
const voiceAudio = $input.item.binary?.audio_response || null;

// Extract the actual response text
let responseText = agentResponse.output || agentResponse.content || agentResponse.message || 'Thank you for contacting Alpine Peak Roofing!';

// Create webhook response
const webhookResponse = {
  success: true,
  message: responseText,
  session_id: inputData.session_id,
  timestamp: new Date().toISOString(),
  input_type: inputData.input_type,
  audio_url: null, // Will be populated if voice response
  metadata: {
    intent: inputData.intent,
    priority: inputData.priority,
    email_captured: inputData.has_email,
    tools_used: agentResponse.intermediateSteps?.length || 0,
    response_format: 'text'
  }
};

// Add voice-specific data if available
if (inputData.input_type === 'voice' && voiceAudio) {
  webhookResponse.audio_url = 'data:audio/mp3;base64,' + voiceAudio.data;
  webhookResponse.metadata.response_format = 'voice';
}

// Add call-to-action based on intent
if (inputData.intent === 'emergency') {
  webhookResponse.cta = {
    type: 'emergency_call',
    action: 'Call (970) 446-8995 immediately',
    urgent: true
  };
} else if (inputData.intent === 'scheduling') {
  webhookResponse.cta = {
    type: 'schedule',
    action: 'Schedule consultation',
    link: 'https://calendly.com/jimmy-agenticpersonnel/30min'
  };
} else {
  webhookResponse.cta = {
    type: 'contact',
    action: 'Learn more about our services',
    link: 'https://calendly.com/jimmy-agenticpersonnel/30min'
  };
}

return {
  json: webhookResponse
};
